window.__timelines = window.__timelines || {};
const tl = gsap.timeline({ paused: true });

// Pre-set entrance states (allowed: this runs synchronously at setup,
// before the paused timeline defines the seekable animation).
gsap.set("#card-wrap", { opacity: 0, y: 22, scale: 0.95, transformOrigin: "left center" });
gsap.set(["#sw-pink", "#sw-peach", "#sw-magenta"], {
  opacity: 0,
  scale: 0.6,
  transformOrigin: "center bottom",
});
gsap.set("#gradient-bar", { opacity: 0 });
gsap.set(".gradient-bar-fill", { scaleX: 0 });

// ---- Card entrance ----
tl.to(
  "#card-wrap",
  { opacity: 1, y: 0, scale: 1, duration: 0.6, ease: "power2.out" },
  0.0
);

// ---- Staggered swatch reveals, timed to spoken color words ----
// "pink"    source 671.76s  -> 3.26s
tl.to(
  "#sw-pink",
  { opacity: 1, scale: 1, duration: 0.45, ease: "power2.out" },
  3.26
);
// "peach"   source 672.60s  -> 4.10s
tl.to(
  "#sw-peach",
  { opacity: 1, scale: 1, duration: 0.45, ease: "power2.out" },
  4.1
);
// "magenta" source 674.14s  -> 5.64s
tl.to(
  "#sw-magenta",
  { opacity: 1, scale: 1, duration: 0.45, ease: "power2.out" },
  5.64
);

// ---- Unifying gradient bar, right after the last chip lands ----
tl.to("#gradient-bar", { opacity: 1, duration: 0.2, ease: "power2.out" }, 6.2);
tl.to(
  ".gradient-bar-fill",
  { scaleX: 1, duration: 0.6, ease: "power2.out" },
  6.2
);

// ---- Clean exit before the clip ends ----
tl.to(
  "#card-wrap",
  { opacity: 0, y: -14, scale: 0.97, duration: 0.8, ease: "power2.in" },
  7.3
);

window.__timelines["main"] = tl;

