const fs = require("fs");
const zlib = require("zlib");

function readPng(path) {
  const buf = fs.readFileSync(path);
  let off = 8;
  let width, height, bitDepth, colorType;
  const idatChunks = [];
  while (off < buf.length) {
    const len = buf.readUInt32BE(off);
    const type = buf.toString("ascii", off + 4, off + 8);
    const data = buf.slice(off + 8, off + 8 + len);
    if (type === "IHDR") {
      width = data.readUInt32BE(0);
      height = data.readUInt32BE(4);
      bitDepth = data[8];
      colorType = data[9];
    } else if (type === "IDAT") {
      idatChunks.push(data);
    }
    off += 8 + len + 4;
  }
  const raw = zlib.inflateSync(Buffer.concat(idatChunks));
  const channels = colorType === 6 ? 4 : colorType === 2 ? 3 : 1;
  const bpp = channels; // bitDepth 8 assumed
  const stride = width * bpp;
  const pixels = Buffer.alloc(height * stride);
  let rawOff = 0;
  for (let y = 0; y < height; y++) {
    const filter = raw[rawOff]; rawOff++;
    const rowStart = y * stride;
    for (let x = 0; x < stride; x++) {
      const rawByte = raw[rawOff + x];
      let a, b, c;
      a = x >= bpp ? pixels[rowStart + x - bpp] : 0;
      b = y > 0 ? pixels[rowStart - stride + x] : 0;
      c = (x >= bpp && y > 0) ? pixels[rowStart - stride + x - bpp] : 0;
      let val;
      if (filter === 0) val = rawByte;
      else if (filter === 1) val = rawByte + a;
      else if (filter === 2) val = rawByte + b;
      else if (filter === 3) val = rawByte + ((a + b) >> 1);
      else if (filter === 4) {
        const p = a + b - c;
        const pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
        const pr = (pa <= pb && pa <= pc) ? a : (pb <= pc ? b : c);
        val = rawByte + pr;
      }
      pixels[rowStart + x] = val & 0xff;
    }
    rawOff += stride;
  }
  return { width, height, channels, pixels };
}

const img = readPng("verify/decoded_5.9.png");
function px(x, y) {
  const i = (y * img.width + x) * img.channels;
  return [img.pixels[i], img.pixels[i+1], img.pixels[i+2], img.channels === 4 ? img.pixels[i+3] : 255];
}

